WITH unified_returns AS (SELECT cr_item_sk AS item_sk, cr_return_quantity AS return_qty, cr_return_amount AS return_amt, cr_returned_date_sk AS return_date_sk FROM catalog_returns UNION ALL SELECT sr_item_sk AS item_sk, sr_return_quantity AS return_qty, sr_return_amt_inc_tax AS return_amt, sr_returned_date_sk AS return_date_sk FROM store_returns), item_agg AS (SELECT item_sk, SUM(return_qty) AS total_return_qty, SUM(return_amt) AS total_return_amt, COUNT(*) AS return_events FROM unified_returns GROUP BY item_sk), ranked_items AS (SELECT item_sk, total_return_qty, total_return_amt, return_events, ROW_NUMBER() OVER (ORDER BY total_return_qty DESC) AS rn FROM item_agg) SELECT item_sk, total_return_qty, total_return_amt, return_events FROM ranked_items WHERE rn <= 5 ORDER BY total_return_qty DESC
